import sys
from array import array
import typing as Tp

def input():
	return sys.stdin.buffer.readline().decode('utf-8')

def output(*args):
	sys.stdout.buffer.write(('\n'.join(map(str, args)) + '\n').encode('utf-8'))

def main():
	n = int(input())
	a = [list(map(float, input().split())) for _ in range(3)]
	dp = [[[-1e+18] * 2 for _ in range(3)] for _ in range(n + 1)]
	dp[0][0][0] = 0.0
	for i in range(n):
		for j in range(3):
			dp[i + 1][j][0] = max(dp[i + 1][j][0], dp[i][j][0] + a[j][i])
			if j > 0:
				dp[i + 1][j - 1][0] = max(dp[i + 1][j - 1][0], dp[i][j][0] + a[j][i] + a[j - 1][i])
			if j < 2:
				dp[i + 1][j + 1][0] = max(dp[i + 1][j + 1][0], dp[i][j][0] + a[j][i] + a[j + 1][i])
		dp[i + 1][0][1] = max(dp[i + 1][0][1], dp[i][0][0] + a[0][i] + a[1][i] + a[2][i], dp[i][0][1] + a[0][i] + a[1][i] + a[2][i])
		dp[i + 1][2][0] = max(dp[i + 1][2][0], dp[i][0][0] + a[0][i] + a[1][i] + a[2][i], dp[i][0][1] + a[0][i] + a[1][i] + a[2][i])
		dp[i + 1][2][1] = max(dp[i + 1][2][1], dp[i][2][0] + a[0][i] + a[1][i] + a[2][i], dp[i][2][1] + a[0][i] + a[1][i] + a[2][i])
		dp[i + 1][0][0] = max(dp[i + 1][0][0], dp[i][2][0] + a[0][i] + a[1][i] + a[2][i], dp[i][2][1] + a[0][i] + a[1][i] + a[2][i])
	print(round(dp[-1][2][0]))
main()
